async function main() {
  let inserted = 0, updated = 0;
  for (const p of POSTS) {
    for (const locale of LOCALES) {
      for (const [field, value] of [["title", p.t[locale]], ["excerpt", p.e[locale]]] as const) {
        const result = await db.execute(sql`
          INSERT INTO translations (translatable_type, translatable_id, locale, field_name, value,
                                    is_machine_translated, is_reviewed, reviewed_by, reviewed_at)
          VALUES ('blog_post', ${p.id}, ${locale}, ${field}, ${value}, false, true, 'manual-wave2.20b', NOW())
          ON CONFLICT (translatable_type, translatable_id, locale, field_name)
          DO UPDATE SET value = EXCLUDED.value, is_machine_translated = false, is_reviewed = true,
                        reviewed_by = 'manual-wave2.20b', reviewed_at = NOW(), updated_at = NOW()
          RETURNING (xmax = 0) AS inserted
        `);
        const row = Array.from(result as any)[0] as any;
        if (row?.inserted) inserted++; else updated++;
      }
    }
  }
  console.log(`Wave 2.20b complete: inserted=${inserted} updated=${updated}`);
  console.log(`Total: ${inserted + updated} (${POSTS.length} posts × ${LOCALES.length} locales × 2 fields)`);
  process.exit(0);
}
main().catch((e) => { console.error(e); process.exit(1); });
